"""Offline corpus navigation for the development decision baseline."""

PAGE = r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'">
<title>Property · Development review</title><style>
:root{font:14px/1.6 'Avenir Next','Segoe UI',sans-serif;color:#272d29;background:#fbfaf7;--muted:#737a6c;--line:#dedfd6;--accent:#536e42}*{box-sizing:border-box}body{margin:0}header{padding:23px 4vw;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{font:25px Georgia,serif;letter-spacing:-1px}.brand small{font:10px 'Avenir Next',sans-serif;letter-spacing:1.5px;margin-left:15px;color:var(--muted)}.run{font-size:11px;color:var(--muted)}main{max-width:1240px;margin:auto;padding:45px 4vw 80px}.eyebrow{text-transform:uppercase;letter-spacing:1.8px;font-size:10px;color:var(--muted)}h1{font:37px/1.2 Georgia,serif;letter-spacing:-.8px;margin:13px 0 15px}p{max-width:760px;color:#66705e}.stats{display:flex;flex-wrap:wrap;gap:25px;font-size:12px;margin:26px 0;color:var(--muted)}.stats strong{font-size:17px;font-weight:500;color:#374a2d;padding-right:4px}.controls{display:flex;justify-content:space-between;gap:14px;align-items:center;margin-top:36px;border-bottom:1px solid var(--line);padding-bottom:12px}input,select{font:inherit;color:inherit;background:transparent;border:1px solid var(--line);border-radius:4px;padding:8px 11px}input{min-width:280px}a:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.column-head,.case{display:grid;grid-template-columns:105px minmax(250px,1fr) 145px 140px 115px;gap:20px;align-items:center}.column-head{font-size:10px;letter-spacing:1px;text-transform:uppercase;color:var(--muted);padding:16px 12px 10px}.case{text-decoration:none;color:inherit;padding:20px 12px;border-top:1px solid var(--line)}.case:hover{background:#eff2e8}.case:last-child{border-bottom:1px solid var(--line)}.case-id{font-size:12px;font-weight:600}.cutoff,.secondary{font-size:11px;color:var(--muted);margin-top:4px;font-weight:400}.title{font-size:14px;font-weight:500}.disposition{font-size:12px}.review{font-size:11px}.warning{color:#8b5b31}.quiet{color:var(--muted)}.state{font-size:11px}.hidden{display:none!important}.empty{padding:40px 0;color:var(--muted)}details{font-size:11px;color:var(--muted);margin-top:34px}summary{cursor:pointer}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:11px/1.5 ui-monospace,monospace}.footnote{font-size:12px;margin-top:27px}.scope{display:inline-block;color:#536e42;background:#edf1e8;padding:3px 9px;border-radius:20px;font-size:10px}.completion{font-size:12px;color:var(--muted)}
@media(max-width:950px){.column-head,.case{grid-template-columns:85px minmax(170px,1fr) 120px 120px;gap:14px}.state{display:none}.column-head span:last-child{display:none}main{padding:34px 4vw}}
@media(max-width:650px){header{padding:18px}.brand small{display:block;margin:4px 0 0}.run{font-size:10px}main{padding:30px 20px}.controls{display:block}input{width:100%;min-width:0}select{margin-top:10px;max-width:100%}.column-head{display:none}.case{grid-template-columns:75px 1fr;gap:7px 12px;padding:20px 0}.disposition{grid-column:2}.review{grid-column:2}.stats{gap:14px}.scope{font-size:9px}.completion{margin-top:10px}h1{font-size:31px}}
</style></head><body><header><div class="brand">Property.<small>EVIDENCE WORKSPACE</small></div><div class="run" id="run"></div></header><main><div class="eyebrow">Development baseline</div><h1>From evidence to a decision.</h1><p>Browse every checkpoint: what was known, what the agent chose, its rationale and citations. Later observed actions are kept separate for review.</p><span class="scope">Property 001–040 · development corpus</span><div class="stats" id="stats"></div><div class="controls"><input type="search" id="search" aria-label="Search cases" placeholder="Search a case or issue…"><select id="filter" aria-label="Filter review status"><option value="all">All checkpoints</option><option value="decisions">Decision available</option><option value="pending">No decision available</option><option value="repair">Decision reference review</option><option value="support">Decision support review</option><option value="uncertain">Evidence uncertainty</option></select><span class="completion" id="count" aria-live="polite"></span></div><div class="column-head"><span>Case</span><span>What happened</span><span>Agent decision</span><span>Review state</span><span>Run state</span></div><div id="cases"></div><p class="footnote">Review labels describe available artifacts and deterministic checks. They are not semantic correctness scores. Consult split labels and the frozen protocol before interpreting generalization. Historical correspondence is model-judged and is not operational correctness.</p><div id="evaluation"></div><div id="cache"></div><details><summary>Baseline prompt and run metadata</summary><pre id="metadata"></pre></details></main><script type="application/json" id="data">__CORPUS_PAYLOAD__</script><script>
const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),words=v=>String(v??'Not available').replaceAll('_',' ');
$('run').textContent=D.run;$('metadata').textContent=JSON.stringify(D.metadata,null,2);
const evaluation=D.metadata.evaluation;if(evaluation){$('evaluation').innerHTML=`<h2>Evaluation by split</h2><p>${esc(evaluation.meaning)}</p><table><thead><tr><th>Split</th><th>Cases</th><th>Valid decisions</th><th>Authority/completion checks</th><th>Historical correspondence</th></tr></thead><tbody>${Object.entries(evaluation.splits).map(([split,v])=>`<tr><td>${esc(words(split))}</td><td>${v.denominator}</td><td>${v.decision_structurally_valid}</td><td>${v.decision_evidence_compatible}</td><td>${Object.entries(v.overall_correspondence).map(([k,n])=>`${n} ${esc(k)}`).join(' · ')}</td></tr>`).join('')}</tbody></table><details><summary>Full evaluation metrics and per-case judge results</summary><pre>${esc(JSON.stringify(evaluation,null,2))}</pre></details>`}
const cache=D.metadata.cache_accounting;if(cache){$('cache').innerHTML=`<details><summary>Provider cache usage by phase</summary><p>${esc(cache.meaning)}</p><table><thead><tr><th>Phase</th><th>Cached input tokens</th><th>Cache write tokens</th><th>Missing reports (read / write)</th></tr></thead><tbody>${Object.entries(cache.by_phase).map(([phase,v])=>`<tr><td>${esc(phase)}</td><td>${v.cached_tokens}</td><td>${v.cache_write_tokens}</td><td>${v.calls_missing_cached_tokens} / ${v.calls_missing_cache_write_tokens} of ${v.calls}</td></tr>`).join('')}</tbody></table></details>`}
$('stats').innerHTML=`<span><strong>${D.entries.length}</strong> checkpoints included</span><span><strong>${D.entries.filter(e=>e.has_decision).length}</strong> with decisions</span><span><strong>${D.entries.filter(e=>e.repair).length}</strong> with reference issues</span><span><strong>${D.entries.filter(e=>e.uncertainties||e.gaps||e.evidence_checks).length}</strong> with uncertain evidence</span>`;
function render(){const query=$('search').value.toLowerCase(),filter=$('filter').value,rows=D.entries.filter(e=>(e.case+' '+e.title+' '+e.disposition).toLowerCase().includes(query)&&(filter==='all'||filter==='decisions'&&e.has_decision||filter==='pending'&&!e.has_decision||filter==='repair'&&e.repair||filter==='support'&&e.support_review||filter==='uncertain'&&(e.uncertainties||e.gaps||e.evidence_checks)));$('count').textContent=rows.length+' of '+D.entries.length;$('cases').innerHTML=rows.map(e=>`<a class="case" href="${esc(e.href)}"><div class="case-id">${esc(e.case.replace('property-','Case '))}<div class="cutoff">Through event ${esc(e.cutoff)}${e.split?` · ${esc(words(e.split))}`:''}</div></div><div><div class="title">${esc(e.title)}</div><div class="secondary">${e.records} claims · ${e.gaps} evidence gaps${e.evidence_checks?' · '+e.evidence_checks+' support checks':''}</div></div><div class="disposition">${esc(e.has_decision?words(e.disposition):'No decision')}<div class="secondary">${e.actions} proposals${e.historical_correspondence?` · historical: ${esc(e.historical_correspondence)}`:''}</div></div><div class="review ${e.repair||e.support_review?'warning':'quiet'}">${esc(e.review_state)}${e.uncertainties?`<div class="secondary">${e.uncertainties} uncertainties</div>`:''}</div><div class="state quiet">${esc(words(e.status))}</div></a>`).join('')||'<p class="empty">No checkpoints match these filters.</p>'}
$('search').addEventListener('input',render);$('filter').addEventListener('change',render);render();
document.addEventListener('keydown',e=>{if(e.key==='/'&&document.activeElement.tagName!=='INPUT'){e.preventDefault();$('search').focus()}});
</script></body></html>"""
